import{fetchCohortJSON}from'./current-cohort-loader.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={development:'Original development',supplement:'Supplement',legacy:'Legacy',holdout:'Original holdout · evaluation only',development049:'New development',holdout049:'Fresh holdout · sealed qualitative review',diagnostic049:'Paired diagnostic variants'};
const verdict=v=>v==='supported'?'Supported exploration':v==='needs-clarification'?'Needs direct clarification':v==='unsupported'?'Contradicted interest':'Not qualitatively reviewed';
const profile=id=>'./model-lab.html?case='+encodeURIComponent(id);
const career=(id,role)=>'../student-view.html?case='+encodeURIComponent(id)+'&replay=final#/journey/profession/'+encodeURIComponent(role);
const external=(url,text)=>/^https:\/\//.test(url||'')?'<a href="'+h(url)+'" target="_blank" rel="noopener">'+h(text)+'</a>':h(text);
const judgment=(name,v)=>v?`<details><summary>${h(name)} · ${h(verdict(v.label))}</summary><p>${h(v.reason)}</p><blockquote>${h(v.quote)}</blockquote></details>`:'';
export function calibration054Rows(data,{cohort='base',issue='all',education='all',query=''}={}){
 const q=query.trim().toLowerCase(),degree=education==='degree';
 return data.rows.filter(r=>(cohort==='all'||cohort==='base'&&r.phase!=='diagnostic049'||cohort===r.phase)&&(!q||[r.id,r.name,...r.top.map(p=>p.title),...r.missingDirections.map(p=>p.family)].join(' ').toLowerCase().includes(q))&&(issue==='all'||issue==='clarify'&&r.top.some(p=>(!degree||p.degree)&&p.verdict==='needs-clarification')||issue==='any-concern'&&r.top.some(p=>(!degree||p.degree)&&p.anyConcern)||issue==='disagreement'&&r.top.some(p=>(!degree||p.degree)&&p.reviewerDisagreement)||issue==='no-top'&&r.flags.noTop||issue==='missing'&&r.flags.missingDirections||issue==='contradiction'&&r.flags.contradiction||issue==='sealed'&&!r.reviewed));
}
export function calibration054Case(r,{education='all',open=false}={}){
 const top=r.top.filter(p=>education!=='degree'||p.degree),d=r.discovery.filter(p=>education!=='degree'||p.degree);
 return `<details class="audit-card" ${open?'open':''}><summary><strong>${h(r.name)}</strong> · ${h(r.id)} · ${h(labels[r.phase])}<small>${r.reviewed?h(r.priority)+' review priority':'Not qualitatively reviewed'} · ${r.top.length} current engine Top · ${r.reviewed?r.top.filter(p=>p.verdict==='needs-clarification').length+' Top claims needing clarification':'Top claim review unavailable'} ${r.flags.missingDirections?' · exploration gaps recorded':''}</small></summary><p>${h(r.reviewStatus)}</p><p><a href="${h(profile(r.id))}">Full biography, characteristics and original answers</a> · <a href="../student-view.html?case=${h(r.id)}&replay=final#/journey/explore">Current interactive exploration</a></p>${r.summary?'<p>'+h(r.summary)+'</p>':''}${!r.reviewed?'<p class="audit-note">'+(r.phase==='holdout049'?'These fixed-rule results are shown separately. No biography-based qualitative judgment or tuning was performed in this audit.':'A paired control checks that changes in identity, support or practical context do not alter interest matches. It is not an extra independent student.')+'</p>':''}${r.noTop?`<section class="audit-note"><h3>No Top: ${h(r.noTop.status.replaceAll('-',' '))}</h3><blockquote>${h(r.noTop.quote)}</blockquote><p>${h(r.noTop.reason)}</p><p><strong>Directions to investigate:</strong> ${r.noTop.directions.map(h).join(' · ')}</p><p><strong>Next question:</strong> ${h(r.noTop.followup)}</p></section>`:''}<h3>Current engine Top and separate evidence review</h3><p>Original answers and Top lists are preserved. The AI judgment below is a developer audit, not a new student answer or eligibility gate.</p><div class="audit-grid">${top.map(p=>`<article class="audit-card"><h4><a href="${h(career(r.id,p.id))}">${h(p.title)}</a></h4><p>${p.degree?'College / graduate route':'Other training route'} · engine: specific interests supported</p><p><strong>Review: ${h(verdict(p.verdict))}</strong>${p.reviewerDisagreement?' · reviewers disagreed; third judgment recorded':''}${p.anyConcern&&p.verdict==='supported'?' · at least one reviewer still requested clarification':''}</p>${judgment('First AI review',p.first)}${judgment('Second AI review',p.second)}${judgment('Third AI judgment',p.adjudication)}${p.anyConcern?`<section><strong>Follow-up before strengthening the claim</strong><p>${h(p.followup)}</p><ul>${p.questions.map(q=>'<li>'+h(q.prompt)+'<small>'+h(q.id)+'</small></li>').join('')}</ul><p>These prompts may already have an inferred Yes. Ask the student directly after a neutral example; do not fabricate another Yes to improve coverage. Unfamiliar remains unresolved.</p></section>`:''}<details><summary>Exact saved supporting evidence</summary><ul>${(p.evidence||[]).map(e=>'<li>'+h(e.prompt)+'<small>'+h(e.source==='student'?'saved simulated response':e.source)+' · '+h(e.confidence)+'</small><p>'+h(e.evidence||e.text)+'</p></li>').join('')}</ul></details></article>`).join('')||'<p>No current Top in this education view. This does not establish that no suitable career exists.</p>'}</div>${r.missingDirections.length?`<h3>Underrepresented directions in the first 12</h3><p>These are review nominations, not confirmed matches or proof of absence from the full 457 inventory.</p>${r.missingDirections.map(p=>'<article class="audit-card"><h4>'+h(p.family)+'</h4><blockquote>'+h(p.quote)+'</blockquote><p>'+h(p.reason)+'</p><p><strong>Next question:</strong> '+h(p.followup)+'</p></article>').join('')}`:''}<details><summary>First 12 discovery and relevance judgments</summary><ul>${d.map(p=>'<li><a href="'+h(career(r.id,p.id))+'">'+h(p.title)+'</a> · '+h(p.judgment?.label||'not reviewed')+'<p>'+h(p.judgment?.reason||'Fresh holdout or diagnostic result; no qualitative judgment.')+'</p></li>').join('')}</ul></details></details>`;
}
export async function mountCalibration054(root){
 if(!root)return;try{
  const data=await fetchCohortJSON('./calibration-054-data.json'),s=data.summary;
  root.innerHTML=`<p>Audit 0.54 of fixed 0.53 matching rules · ${h(data.generatedAt.slice(0,10))}</p><p class="audit-note"><strong>Full synthetic review is not exhaustive human calibration.</strong> ${s.reviewed} base profiles received biography-led AI reviews. All ${s.topClaims} current Top claims received two AI judgments; disagreements received a third. The 12 fresh holdout profiles remain outside qualitative review. Original profiles, saved answers, matching rules and coverage counts are unchanged.</p><div class="audit-stats"><div class="audit-card"><strong>${s.reviewed}/172</strong>base profiles qualitatively reviewed</div><div class="audit-card"><strong>${s.majority['needs-clarification']||0}/${s.topClaims}</strong>reviewed Top claims need direct clarification</div><div class="audit-card"><strong>${s.noTop}</strong>base models without supported Top<br>18 reviewed;1 fresh holdout sealed</div><div class="audit-card"><strong>${s.missingDirectionModels}</strong>reviewed profiles with underrepresented directions</div></div><p>“Supported exploration” means a credible direction to investigate. It does not establish aptitude, professional readiness, student choice or career success. AI reviewers share a model family and their majority is not ground truth.</p><div class="audit-scroll"><table><caption>Fixed engine coverage and evidence-review findings · cohorts kept separate</caption><thead><tr><th>Cohort</th><th>Models</th><th>Reviewed</th><th>Engine Top</th><th>Engine degree Top</th><th>Review needs clarification: claims</th><th>Degree claims needing clarification</th></tr></thead><tbody>${data.cohorts.map(c=>'<tr><th>'+h(labels[c.phase])+'</th><td>'+c.n+'</td><td>'+c.reviewed+'</td><td>'+c.engineTop+'</td><td>'+c.engineDegreeTop+'</td><td>'+(c.reviewed?c.reviewNeedsClarification:'not reviewed')+'</td><td>'+(c.reviewed?c.degreeNeedsClarification:'not reviewed')+'</td></tr>').join('')}</tbody></table></div><p>Reviewers initially agreed on ${s.agreement.agree}/${s.agreement.claims} claims (${(s.agreement.observed*100).toFixed(1)}%; Cohen’s κ ${s.agreement.kappa.toFixed(3)}). ${s.agreement.disagree} disagreements received a third judgment. This measures AI coding consistency, not student accuracy. First 12 judgments: ${s.discovery['supported-direction']} supported directions, ${s.discovery['plausible-adjacent']} plausible adjacent, ${s.discovery['needs-clarification']} needing clarification, ${s.discovery.implausible||0} conflicting with an expressed preference.</p><p><a href="#model-audit">Inspect every model ↓</a> · <a href="#external-audit">Other services ↓</a> · <a href="#sensitivity-audit">Answer sensitivity ↓</a> · <a href="#inventory-audit">Missing inventory ↓</a> · <a href="./docs/calibration-054-pilot-kit.md.html">Student/counselor pilot kit</a> · <a href="./calibration-054-data.json" download>Full auditable data · JSON</a> · <a href="./calibration-054-cases.csv" download>Case summary · CSV</a></p>${data.verification?'<p><strong>Release checks:</strong> '+data.verification.software.passed+' automated tests passed; five independent metric checks passed. <a href="./validation/calibration-054-test-results.json">Recorded checks and browser verification</a>.</p>':''}<section id="model-audit"><h2>Full cohort and follow-up questions</h2><form id="audit-controls"><label>Cohort <select name="cohort" aria-label="Cohort"><option value="base">All 172 base profiles</option><option value="all">All 184 including diagnostics</option>${Object.entries(labels).map(([k,v])=>'<option value="'+k+'">'+h(v)+'</option>').join('')}</select></label><label>Review filter <select name="issue" aria-label="Review filter"><option value="all">All results</option><option value="clarify">Top needs clarification · majority review</option><option value="any-concern">Any reviewer requests clarification</option><option value="disagreement">Reviewers disagreed</option><option value="no-top">No current supported Top</option><option value="missing">Underrepresented directions</option><option value="contradiction">Discovery conflicts with stated preference</option><option value="sealed">Not qualitatively reviewed</option></select></label><label>Professions <select name="education" aria-label="Professions"><option value="all">All training routes</option><option value="degree">College and graduate only</option></select></label><label>Find model or direction <input name="query" aria-label="Find model or direction" type="search" placeholder="Name, ID, profession or direction"></label><button type="submit">Apply</button></form><p>Education changes displayed career claims and claim-based filters. Model counts include profiles with no Top; original denominators remain unchanged.</p><p id="audit-status" role="status"></p><div id="audit-rows"></div></section><section id="external-audit"><h2>Actual external comparisons</h2><p>The earlier official O*NET 18-input comparison and two CareerOneStop sessions agree closely with the underlying broad scoring. Both use O*NET. The additional Truity runs below use a different questionnaire and implementation, while sharing Holland theory; they are not independent predictive validation.</p><div class="audit-grid">${data.external.cases.map(c=>`<article class="audit-card"><h3>${h(data.rows.find(r=>r.id===c.id)?.name)} · ${h(c.id)}</h3><p>${external(c.url,'Observed Truity free result')} · leading interest: ${h(c.leadingTheme)}</p><p>94 frozen proxy responses; ${c.neutralProxyCount} unresolved entries entered as neutral because the provider requires a rating. These are not actual student answers.</p><p>${h(c.interpretation)}</p><details><summary>All ${c.careers.length} displayed external career suggestions</summary><ul>${c.careers.map(t=>'<li>'+h(t)+'</li>').join('')}</ul></details><details><summary>Provider-displayed theme scores · not comparable to our raw sums</summary><p>${Object.entries(c.displayedScores).map(([k,v])=>h(k)+': '+v).join(' · ')}</p></details></article>`).join('')}</div><p>Both broad leads are coherent, but the free suggestions include careers whose distinctive interests were not established. Truity’s mechanical case includes electrical engineering while our supported Top is mechanical engineering. This is a reason to compare branches, not force agreement. Its free list is incomplete and appears ordered by earnings; numeric relevance-rank correlation and full-list recall are unavailable. No paid report, account or real student data was used.</p><p><a href="./docs/external-validation-053-2026-10-19.md.html">Official scoring comparison</a> · <a href="./docs/careeronestop-comparison-053-2026-10-19.md.html">CareerOneStop comparison</a></p></section><section id="sensitivity-audit"><h2>One-answer sensitivity and paired controls</h2><p>Each valid official answer was separately moved one response step up/down, within 1–5, without changing saved histories. This stress-tests broad correlations, not supportedTop outcomes, response reliability or the probability of a real preference change. Top 12 overlap includes ties at the cutoff.</p><div class="audit-scroll"><table><thead><tr><th>Cohort</th><th>Profiles</th><th>Perturbations</th><th>Profiles with a broad Top 12 change</th><th>Profiles with a strong-set change</th><th>Most strong labels changed by one step</th></tr></thead><tbody>${data.sensitivity.cohorts.map(c=>'<tr><th>'+h(labels[c.phase])+'</th><td>'+c.n+'</td><td>'+c.scenarios+'</td><td>'+c.profilesWithTop12Change+'</td><td>'+c.profilesWithStrongSetChange+'</td><td>'+c.maximumStrongFlips+'</td></tr>').join('')}</tbody></table></div><p>A large set change can occur in a weakly differentiated profile. These are threshold crossings, not evidence that dozens of real interests changed. No weights or cutoffs were tuned to these outcomes. All 184 context substitutions and all 12 paired diagnostic comparisons retained identical interest correlations and support; 6 authored engineering/health boundary scenarios are now executed as software fixtures.</p><details><summary>Per-profile sensitivity</summary><div class="audit-scroll"><table><thead><tr><th>Model</th><th>Broad candidates with vectors</th><th>One-step scenarios</th><th>Largest strong-set change</th><th>Minimum Top 12 overlap · Jaccard</th></tr></thead><tbody>${data.sensitivity.records.map(r=>'<tr><th>'+h(r.id)+'</th><td>'+r.availableVectors+'</td><td>'+r.scenarios+'</td><td>'+r.maxStrongFlips+'</td><td>'+(r.minTopJaccard===null?'unavailable':r.minTopJaccard.toFixed(3))+'</td></tr>').join('')}</tbody></table></div></details></section><section id="inventory-audit"><h2>All 13 previously identified inventory gaps</h2><p>Seven distinct arts/craft professions warrant discovery content; four require clearly described later-stage pathways; two need scope review. These are reviewed proposals, not activated matching entries. Many have variable education routes: adding them must not inflate a “college required” count.</p>${data.inventory.map(o=>`<details class="audit-card"><summary><strong>${h(o.title)}</strong> · ${h(o.soc)} · ${h(o.decision.replaceAll('-',' '))}</summary><p>${h(o.reason)}</p><p>${h(o.educationCaveat)}</p><p>${h(o.experienceCaveat)}</p><p>${external(o.sourceUrl,'Official occupation source')}</p>${o.possibleModels.length?'<ul>'+o.possibleModels.map(m=>'<li><a href="'+h(profile(m.id))+'">'+h(m.id)+'</a><blockquote>'+h(m.quote)+'</blockquote>'+h(m.reason)+'</li>').join('')+'</ul>':'<p>No biography-supported nomination made.</p>'}<p><strong>Neutral follow-up:</strong> ${h(o.neutralFollowup)}</p></details>`).join('')}</section><section><h2>What remains</h2><ul>${data.remaining.map(r=>'<li><strong>'+h(r.task)+'</strong> · '+h(r.status)+'<small>'+h(r.dependency)+'</small></li>').join('')}</ul><p><a href="./docs/calibration-054-pilot-kit.md.html">Prepared student and counselor protocol</a> · <a href="./calibration-054-session-template.csv" download>Blank collection ledger</a></p></section>`;
  const form=root.querySelector('#audit-controls'),params=new URL(location.href).searchParams;
  for(const key of['cohort','issue','education','query'])if(params.has(key)&&form.elements[key]){const el=form.elements[key];if(el.tagName!=='SELECT'||[...el.options].some(o=>o.value===params.get(key)))el.value=params.get(key);}
  const draw=()=>{const options=Object.fromEntries(new FormData(form)),rs=calibration054Rows(data,options);root.querySelector('#audit-status').textContent=rs.length+' profiles shown · '+rs.filter(r=>r.reviewed).length+' qualitatively reviewed. Fresh holdout and diagnostics retain their separate status.';root.querySelector('#audit-rows').innerHTML=rs.map(r=>calibration054Case(r,{education:options.education,open:rs.length===1})).join('')||'<p>No profiles meet these filters. Clear a filter to return to the cohort.</p>';};
  form.addEventListener('submit',e=>{e.preventDefault();draw();});draw();
 }catch(e){root.innerHTML='<p>'+h(e.message)+'. Reload to try again.</p>';}
}
